import java.util.*;class Solution{public List<List<Integer>> levelOrder(TreeNode r){List<List<Integer>>o=new ArrayList<>();if(r==null)return o;Queue<TreeNode>q=new ArrayDeque<>();q.add(r);while(!q.isEmpty()){int n=q.size();List<Integer>v=new ArrayList<>();while(n-->0){TreeNode x=q.remove();v.add(x.val);if(x.left!=null)q.add(x.left);if(x.right!=null)q.add(x.right);}o.add(v);}return o;}}
